# Part-2 AI pose prompts. Run: python stil/canli/prompts/make_p2a.py  -> p2-a-*.txt
import os

HERE = os.path.dirname(os.path.abspath(__file__))
HEAD = "Use your built-in image_gen tool to generate exactly ONE image, 16:9 landscape. Do not copy or move any files and do not run shell commands; just generate it, then print DONE.\n\n"
BG = "\n\nBackground: ONE flat solid pure magenta (#FF00FF), completely uniform, no shadow, no floor line, no ground, no box, no furniture, no props unless named above. ABSOLUTELY NO text, letters, numbers, logos, watermarks, no other characters. Palette only navy, cream, moon yellow (+ magenta background). No 3D render look, no photorealism, no soft shading.\n"
AI = HEAD + """The FIRST attached image is the APPROVED design of the AI character (silk-screen style); the SECOND is an approved pose drawing of her in this same film. Draw the SAME character, ONE single figure, full body, nothing cropped, centred, at the same scale as the figure in the second image: smooth genderless slender body, cream-white (#F3EFE4) fill with fine navy stipple speckle, a thin navy outline, bald round head, NO face at all except ONE short vertical navy cursor line on the face (exactly like the reference). No clothes, no hair, no ears, no nose, no mouth. Same proportions as the reference.

Camera: a FLAT SIDE VIEW (pure profile), full body. Rules: the head never turns more than 30 degrees from the torso (any turn is a whole-body turn); hands touch exactly what they touch; no extra, missing or doubled limbs, exactly five fingers or a clean mitten-like hand, no extra feet; exactly one figure; no text; no props unless named. """

P = {}
P['p2-a-sit'] = AI + "Pose: she SITS on the edge of a knee-high box (the box is NOT drawn; she appears to sit on invisible air at seat height), her WHOLE BODY facing LEFT in profile: back upright, thighs horizontal pointing LEFT, lower legs hanging STRAIGHT DOWN from the knees (vertical shins), both feet relaxed and hanging, the two legs nearly overlapping in the side view, both hands resting flat on the (undrawn) seat surface beside her hips, the cursor line on the LEFT side of her head. Calm, relaxed." + BG
P['p2-a-step1'] = AI + "Pose: a WALKING STRIDE, CONTACT phase, her WHOLE BODY facing RIGHT in profile: the front leg stretched forward with its heel just touching down (toes up), the rear leg stretched behind her with the toe still on the ground, legs wide apart, torso upright, arms swinging opposite to the legs (near arm back if the near leg is forward), cursor line on the RIGHT side of her head. Same standing height and head size as the references." + BG
P['p2-a-step2'] = AI + "Pose: a WALKING STRIDE, PASSING phase, her WHOLE BODY facing RIGHT in profile: standing leg straight and vertical under her, the other leg passing beside it with its knee slightly bent and the foot lifting off the ground, legs close together, torso upright, arms hanging near her sides passing each other, cursor line on the RIGHT side of her head. Same standing height and head size as the references." + BG
P['p2-a-step3'] = AI + "Pose: a WALKING STRIDE, CONTACT phase (the mirror of the first stride: the OTHER leg is forward), her WHOLE BODY facing RIGHT in profile: the front leg stretched forward with its heel just touching down (toes up), the rear leg behind her with the toe on the ground, legs wide apart, torso upright, arms swinging opposite to the legs (near arm forward if the near leg is back), cursor line on the RIGHT side of her head. Same standing height and head size as the references." + BG
P['p2-a-trip'] = AI + "Pose: she is STUMBLING mid-stride, her WHOLE BODY facing RIGHT in profile: her rear toe has caught on something behind her (the rear foot is lifted behind with the toe pointing down), the body is pitched FORWARD about 25 degrees, both arms flung forward and up in front of her, balanced on ONE foot (the front foot on the ground), NOT fallen; head follows the body line (pitched with the torso, not twisted), cursor line on the RIGHT side of her head. Same size as the references." + BG
P['p2-a-tap'] = AI + "Pose: she bends slightly FORWARD at the hips, her WHOLE BODY facing RIGHT in profile, the near arm reaching down and forward with a straight index finger, the fingertips just TAPPING the top of an undrawn box whose top is at her KNEE height a little in front of her (the box is NOT drawn: her fingertip simply ends at that spot in the air), the other arm relaxed, both feet on the ground, legs straight, cursor line on the RIGHT side of her head. Same size as the references." + BG
P['p2-a-thumb'] = AI + "Pose: proud and confident, her WHOLE BODY facing LEFT in profile, chest out, standing tall, the near arm raised FORWARD at shoulder height, the forearm bent upward, giving a clear THUMBS-UP: a closed fist with exactly four curled fingers and ONE thumb pointing straight up; the other arm relaxed at her side; cursor line on the LEFT side of her head. Same size as the references." + BG
P['p2-a-squint'] = AI + "Pose: her WHOLE BODY facing LEFT in profile, leaning back slightly, ONE hand raised flat to her forehead with the palm down like a visor, shielding her eyes from a bright light in front of her (the light is not drawn), the other arm relaxed, standing on both feet; the cursor line on the LEFT side of her head is SHORTER than normal (about half length), as if squinting. Same size as the references." + BG
for k, v in P.items():
    open(os.path.join(HERE, k + '.txt'), 'w', encoding='utf8').write(v)
print(len(P), 'prompts')
